scenarios.example_code:
import { registerAgent } from '@projexlight/sdk-agent-runtime';
const { agent_id } = await registerAgent({
  tenant_id, name: 'cs-tier1',
  allowed_tools: ['kb.search', 'tickets.create', 'tickets.update_status'],
  allowed_vector_namespaces: [`tenant:${tenant_id}:knowledge`],
  default_max_steps: 12,
});

import { mintToken, startRun } from '@projexlight/sdk-agent-runtime';
const { token_id } = await mintToken({
  agent_id, persona_id: customer.persona_id, tenant_id,
  ttl_min: 15,
});
const { run_id } = await startRun({
  agent_id, token_id, initial_message: customer.message,
});

// inside the agent loop:
await invokeTool({ run_id, tool: 'billing.refund', args }); 
// → throws ScopeViolation; emits agents.scope.violation.detected.v1.

import { startChaosLeakage } from '@projexlight/sdk-agent-runtime';
startChaosLeakage({
  interval_hours: 1, halt_pipeline_on_failure: true,
});

import { replayRun } from '@projexlight/sdk-agent-runtime';
const replay = await replayRun({ run_id });
// replay = ordered list of { step, kind: 'llm-message' | 'tool-call', payload }
